-- Schema: public
-- =====================================================

-- -------------------------------------------------
-- public.almacenes
-- -------------------------------------------------
CREATE TABLE public.almacenes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo text NOT NULL,
    nombre text NOT NULL,
    direccion text,
    tipo text DEFAULT 'almacen'::text,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

-- -------------------------------------------------
-- public.clientes
-- -------------------------------------------------
CREATE TABLE public.clientes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo_cliente text,
    nombre_razon_social text NOT NULL,
    tipo_documento text,
    numero_documento text,
    complemento text,
    telefono text,
    direccion text,
    correo text,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

-- -------------------------------------------------
-- public.detalle_ventas
-- -------------------------------------------------
CREATE TABLE public.detalle_ventas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    venta_id uuid NOT NULL,
    producto_id uuid NOT NULL,
    almacen_id uuid NOT NULL,
    codigo_producto_snapshot text,
    descripcion_producto text,
    cantidad numeric(16,3) NOT NULL,
    precio_unitario numeric(16,4) NOT NULL,
    tipo_precio text DEFAULT 'pieza'::text NOT NULL,
    descuento numeric(16,2) DEFAULT 0 NOT NULL,
    subtotal numeric(16,2) GENERATED ALWAYS AS (((cantidad * precio_unitario) - descuento)) STORED,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

-- -------------------------------------------------
-- public.facturas_siat
-- -------------------------------------------------
CREATE TABLE public.facturas_siat (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    venta_id uuid NOT NULL,
    cuf text NOT NULL,
    fecha_emision timestamp with time zone NOT NULL,
    numero_factura bigint NOT NULL,
    codigo_sucursal integer DEFAULT 0 NOT NULL,
    codigo_punto_venta integer DEFAULT 0 NOT NULL,
    cuis text NOT NULL,
    cufd text NOT NULL,
    nombre_razon_social text,
    tipo_documento text,
    numero_documento text,
    complemento text,
    monto_total numeric(16,2),
    estado_interno text DEFAULT 'pendiente'::text NOT NULL,
    codigo_descripcion text,
    codigo_estado integer,
    codigo_recepcion text,
    transaccion boolean,
    log text,
    xml_enviado text,
    fecha_respuesta timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

-- -------------------------------------------------
-- public.historial_ventas
-- -------------------------------------------------
CREATE TABLE public.historial_ventas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    venta_id uuid NOT NULL,
    codigo_venta text NOT NULL,
    fecha_venta timestamp with time zone NOT NULL,
    cliente_id uuid,
    usuario_id uuid,
    almacen_id uuid,
    cantidad_total numeric(16,3) DEFAULT 0 NOT NULL,
    productos_diferentes integer DEFAULT 0 NOT NULL,
    subtotal numeric(16,2) DEFAULT 0 NOT NULL,
    descuento_total numeric(16,2) DEFAULT 0 NOT NULL,
    total numeric(16,2) DEFAULT 0 NOT NULL,
    metodo_pago text,
    estado text NOT NULL,
    numero_factura bigint,
    cuf text,
    fecha_facturacion timestamp with time zone,
    fecha_anulacion timestamp with time zone,
    usuario_anulacion_id uuid,
    motivo_anulacion text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

-- -------------------------------------------------
-- public.movimientos_inventario
-- -------------------------------------------------
CREATE TABLE public.movimientos_inventario (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    producto_id uuid NOT NULL,
    almacen_id uuid NOT NULL,
    tipo_movimiento text NOT NULL,
    cantidad numeric(16,3) NOT NULL,
    stock_anterior numeric(16,3),
    stock_resultante numeric(16,3),
    motivo text,
    venta_id uuid,
    detalle_venta_id uuid,
    usuario_id uuid,
    observacion text,
    fecha timestamp with time zone DEFAULT now() NOT NULL
);

-- -------------------------------------------------
-- public.productos
-- -------------------------------------------------
CREATE TABLE public.productos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo_interno text NOT NULL,
    codigo_producto_sin integer,
    nombre text NOT NULL,
    descripcion text,
    numero text,
    medida text,
    codigo_unidad_medida_sin integer,
    largo numeric(14,3),
    ancho numeric(14,3),
    precio_produccion numeric(16,2) DEFAULT 0 NOT NULL,
    precio_1000 numeric(16,2) DEFAULT 0 NOT NULL,
    precio_100 numeric(16,2) DEFAULT 0 NOT NULL,
    precio_12 numeric(16,2) DEFAULT 0 NOT NULL,
    precio_pieza numeric(16,2) DEFAULT 0 NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

-- -------------------------------------------------
-- public.stock_por_almacen
-- -------------------------------------------------
CREATE TABLE public.stock_por_almacen (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    producto_id uuid NOT NULL,
    almacen_id uuid NOT NULL,
    cantidad_disponible numeric(16,3) DEFAULT 0 NOT NULL,
    cantidad_reservada numeric(16,3) DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

-- -------------------------------------------------
-- public.usuarios
-- -------------------------------------------------
CREATE TABLE public.usuarios (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    auth_user_id uuid,
    nombre text NOT NULL,
    apellidos text NOT NULL,
    tipo_documento text DEFAULT 'CI'::text NOT NULL,
    numero_documento text NOT NULL,
    complemento text,
    telefono text,
    correo text,
    rol text DEFAULT 'vendedor'::text NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

-- -------------------------------------------------
-- public.ventas
-- -------------------------------------------------
CREATE TABLE public.ventas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo_venta text NOT NULL,
    fecha_venta timestamp with time zone DEFAULT now() NOT NULL,
    cliente_id uuid,
    usuario_id uuid NOT NULL,
    almacen_local_id uuid,
    subtotal numeric(16,2) DEFAULT 0 NOT NULL,
    descuento_items numeric(16,2) DEFAULT 0 NOT NULL,
    descuento_venta numeric(16,2) DEFAULT 0 NOT NULL,
    descuento_total numeric(16,2) GENERATED ALWAYS AS ((descuento_items + descuento_venta)) STORED,
    total numeric(16,2) GENERATED ALWAYS AS (((subtotal - descuento_items) - descuento_venta)) STORED,
    metodo_pago text,
    estado text DEFAULT 'pendiente'::text NOT NULL,
    inventario_aplicado boolean DEFAULT false NOT NULL,
    fecha_anulacion timestamp with time zone,
    motivo_anulacion text,
    usuario_anulacion_id uuid,
    observacion text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

