-- -------------------------------------------------
-- public.fn_actualizar_historial_venta.17788
-- -------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_actualizar_historial_venta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE

    v_cantidad_total NUMERIC(16,3);
    v_productos_diferentes INTEGER;

    v_numero_factura BIGINT;
    v_cuf TEXT;
    v_fecha_facturacion TIMESTAMPTZ;

BEGIN

    -- No guardamos ventas todavía pendientes
    IF NEW.estado = 'pendiente' THEN
        RETURN NEW;
    END IF;


    SELECT

        COALESCE(
            SUM(cantidad),
            0
        ),

        COUNT(
            DISTINCT producto_id
        )

    INTO

        v_cantidad_total,
        v_productos_diferentes

    FROM public.detalle_ventas

    WHERE venta_id = NEW.id;


    SELECT

        numero_factura,
        cuf,
        fecha_emision

    INTO

        v_numero_factura,
        v_cuf,
        v_fecha_facturacion

    FROM public.facturas_siat

    WHERE venta_id = NEW.id

    LIMIT 1;


    INSERT INTO public.historial_ventas (

        venta_id,

        codigo_venta,
        fecha_venta,

        cliente_id,
        usuario_id,
        almacen_id,

        cantidad_total,
        productos_diferentes,

        subtotal,
        descuento_total,
        total,

        metodo_pago,
        estado,

        numero_factura,
        cuf,
        fecha_facturacion,

        fecha_anulacion,
        usuario_anulacion_id,
        motivo_anulacion

    )
    VALUES (

        NEW.id,

        NEW.codigo_venta,
        NEW.fecha_venta,

        NEW.cliente_id,
        NEW.usuario_id,
        NEW.almacen_local_id,

        v_cantidad_total,
        v_productos_diferentes,

        NEW.subtotal,
        NEW.descuento_total,
        NEW.total,

        NEW.metodo_pago,
        NEW.estado,

        v_numero_factura,
        v_cuf,
        v_fecha_facturacion,

        NEW.fecha_anulacion,
        NEW.usuario_anulacion_id,
        NEW.motivo_anulacion

    )

    ON CONFLICT (venta_id)

    DO UPDATE SET

        codigo_venta =
            EXCLUDED.codigo_venta,

        fecha_venta =
            EXCLUDED.fecha_venta,

        cliente_id =
            EXCLUDED.cliente_id,

        usuario_id =
            EXCLUDED.usuario_id,

        almacen_id =
            EXCLUDED.almacen_id,

        cantidad_total =
            EXCLUDED.cantidad_total,

        productos_diferentes =
            EXCLUDED.productos_diferentes,

        subtotal =
            EXCLUDED.subtotal,

        descuento_total =
            EXCLUDED.descuento_total,

        total =
            EXCLUDED.total,

        metodo_pago =
            EXCLUDED.metodo_pago,

        estado =
            EXCLUDED.estado,

        numero_factura =
            EXCLUDED.numero_factura,

        cuf =
            EXCLUDED.cuf,

        fecha_facturacion =
            EXCLUDED.fecha_facturacion,

        fecha_anulacion =
            EXCLUDED.fecha_anulacion,

        usuario_anulacion_id =
            EXCLUDED.usuario_anulacion_id,

        motivo_anulacion =
            EXCLUDED.motivo_anulacion,

        updated_at =
            NOW();


    RETURN NEW;

END;
$function$
;

-- -------------------------------------------------
-- public.fn_actualizar_updated_at.17771
-- -------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_actualizar_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$
;

-- -------------------------------------------------
-- public.fn_aplicar_inventario_venta.17785
-- -------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_aplicar_inventario_venta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE

    item RECORD;

    v_stock_anterior NUMERIC(16,3);
    v_stock_resultante NUMERIC(16,3);

BEGIN

    -- =====================================================
    -- CONFIRMAR VENTA
    -- =====================================================

    IF
        NEW.estado IN ('confirmada', 'facturada')
        AND OLD.inventario_aplicado = FALSE
    THEN

        IF NOT EXISTS (
            SELECT 1
            FROM public.detalle_ventas
            WHERE venta_id = NEW.id
        ) THEN

            RAISE EXCEPTION
            'No se puede confirmar una venta sin productos.';

        END IF;


        FOR item IN

            SELECT *
            FROM public.detalle_ventas
            WHERE venta_id = NEW.id

        LOOP

            UPDATE public.stock_por_almacen

            SET
                cantidad_disponible =
                    cantidad_disponible - item.cantidad,

                updated_at = NOW()

            WHERE
                producto_id = item.producto_id
                AND almacen_id = item.almacen_id
                AND cantidad_disponible >= item.cantidad

            RETURNING
                cantidad_disponible + item.cantidad,
                cantidad_disponible

            INTO
                v_stock_anterior,
                v_stock_resultante;


            IF NOT FOUND THEN

                RAISE EXCEPTION
                'Stock insuficiente para producto % en almacén %',
                item.producto_id,
                item.almacen_id;

            END IF;


            INSERT INTO public.movimientos_inventario (

                producto_id,
                almacen_id,

                tipo_movimiento,

                cantidad,

                stock_anterior,
                stock_resultante,

                motivo,

                venta_id,
                detalle_venta_id,

                usuario_id

            )
            VALUES (

                item.producto_id,
                item.almacen_id,

                'salida',

                item.cantidad,

                v_stock_anterior,
                v_stock_resultante,

                'Venta confirmada',

                NEW.id,
                item.id,

                NEW.usuario_id

            );

        END LOOP;


        NEW.inventario_aplicado := TRUE;

    END IF;


    -- =====================================================
    -- ANULAR VENTA
    -- =====================================================

    IF
        NEW.estado = 'anulada'
        AND OLD.estado <> 'anulada'
    THEN

        IF
            NEW.motivo_anulacion IS NULL
            OR TRIM(NEW.motivo_anulacion) = ''
        THEN

            RAISE EXCEPTION
            'Debe indicar el motivo de anulación.';

        END IF;


        NEW.fecha_anulacion :=
            COALESCE(
                NEW.fecha_anulacion,
                NOW()
            );


        IF OLD.inventario_aplicado = TRUE THEN

            FOR item IN

                SELECT *
                FROM public.detalle_ventas
                WHERE venta_id = NEW.id

            LOOP

                SELECT cantidad_disponible

                INTO v_stock_anterior

                FROM public.stock_por_almacen

                WHERE
                    producto_id = item.producto_id
                    AND almacen_id = item.almacen_id

                FOR UPDATE;


                IF NOT FOUND THEN

                    v_stock_anterior := 0;


                    INSERT INTO public.stock_por_almacen (

                        producto_id,
                        almacen_id,
                        cantidad_disponible

                    )
                    VALUES (

                        item.producto_id,
                        item.almacen_id,
                        item.cantidad

                    );


                    v_stock_resultante :=
                        item.cantidad;


                ELSE

                    UPDATE public.stock_por_almacen

                    SET
                        cantidad_disponible =
                            cantidad_disponible + item.cantidad,

                        updated_at = NOW()

                    WHERE
                        producto_id = item.producto_id
                        AND almacen_id = item.almacen_id

                    RETURNING cantidad_disponible

                    INTO v_stock_resultante;

                END IF;


                INSERT INTO public.movimientos_inventario (

                    producto_id,
                    almacen_id,

                    tipo_movimiento,

                    cantidad,

                    stock_anterior,
                    stock_resultante,

                    motivo,

                    venta_id,
                    detalle_venta_id,

                    usuario_id

                )
                VALUES (

                    item.producto_id,
                    item.almacen_id,

                    'devolucion_venta',

                    item.cantidad,

                    v_stock_anterior,
                    v_stock_resultante,

                    'Venta anulada',

                    NEW.id,
                    item.id,

                    NEW.usuario_anulacion_id

                );

            END LOOP;


            NEW.inventario_aplicado := FALSE;

        END IF;

    END IF;


    RETURN NEW;

END;
$function$
;

-- -------------------------------------------------
-- public.fn_recalcular_venta.17781
-- -------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_recalcular_venta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_venta_id UUID;
    v_subtotal NUMERIC(16,2);
    v_descuentos NUMERIC(16,2);
BEGIN

    IF TG_OP = 'DELETE' THEN
        v_venta_id := OLD.venta_id;
    ELSE
        v_venta_id := NEW.venta_id;
    END IF;


    SELECT
        COALESCE(
            SUM(cantidad * precio_unitario),
            0
        ),

        COALESCE(
            SUM(descuento),
            0
        )

    INTO
        v_subtotal,
        v_descuentos

    FROM public.detalle_ventas
    WHERE venta_id = v_venta_id;


    UPDATE public.ventas
    SET
        subtotal = v_subtotal,
        descuento_items = v_descuentos
    WHERE id = v_venta_id;


    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;

END;
$function$
;

-- -------------------------------------------------
-- public.fn_validar_detalle_venta.17783
-- -------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_validar_detalle_venta()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_venta_id UUID;
    v_estado TEXT;
BEGIN

    IF TG_OP = 'DELETE' THEN
        v_venta_id := OLD.venta_id;
    ELSE
        v_venta_id := NEW.venta_id;
    END IF;


    SELECT estado
    INTO v_estado
    FROM public.ventas
    WHERE id = v_venta_id;


    IF v_estado IS NULL THEN
        RAISE EXCEPTION 'La venta no existe.';
    END IF;


    IF v_estado <> 'pendiente' THEN
        RAISE EXCEPTION
        'No se puede modificar una venta que ya fue confirmada, facturada o anulada.';
    END IF;


    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;

END;
$function$
;

-- -------------------------------------------------
-- public.rls_auto_enable.17486
-- -------------------------------------------------
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
;

